import{_ as a,c as i,o as e,ag as n}from"./chunks/framework.CA4hJK0u.js";const r=JSON.parse('{"title":"AgentKit 模型网关快速开始指南","description":"","frontmatter":{},"headers":[],"relativePath":"content/9.model-gateway/1.model_gateway_quickstart.md","filePath":"content/9.model-gateway/1.model_gateway_quickstart.md","lastUpdated":1785745052000}'),t={name:"content/9.model-gateway/1.model_gateway_quickstart.md"};function p(l,s,h,d,o,k){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="agentkit-模型网关快速开始指南" tabindex="-1">AgentKit 模型网关快速开始指南 <a class="header-anchor" href="#agentkit-模型网关快速开始指南" aria-label="Permalink to &quot;AgentKit 模型网关快速开始指南&quot;">​</a></h1><p>模型网关提供统一的模型访问调用入口。您可以将火山方舟等模型服务配置为供应商，再创建消费者获取访问密钥，最后通过模型网关的 <code>/chat/completions</code> 接口调用模型。</p><p>本文以火山方舟 <code>doubao-seed-evolving</code> 为例。</p><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h2><p>请先完成 AgentKit CLI 安装，并配置火山引擎 AK/SK：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VOLCENGINE_ACCESS_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_access_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VOLCENGINE_SECRET_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_secret_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="_1-激活模型网关" tabindex="-1">1. 激活模型网关 <a class="header-anchor" href="#_1-激活模型网关" aria-label="Permalink to &quot;1. 激活模型网关&quot;">​</a></h2><p>执行 <code>activate</code> 创建或复用当前账号下的模型网关。是否传入 <code>--apig-gateway-id</code> 决定模型网关类型：</p><ul><li>不传 <code>--apig-gateway-id</code>：创建共享型模型网关，适合快速启动和体验。</li><li>传入 <code>--apig-gateway-id</code>：创建标准型模型网关，适合需要 VPC 内私网访问、自定义入站/出站网络规格，或对稳定性要求更高的生产场景。</li></ul><p>快速启动可以直接创建共享型模型网关：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activate</span></span></code></pre></div><p>如果需要标准型模型网关，请先准备 API 网关实例 ID，再执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apig-gateway-id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_apig_gateway_i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>如果已存在模型网关，CLI 会直接提示已存在，并展示 <code>ModelGatewayId</code> 和当前状态。只有状态为 <code>Running</code> 时，后续配置和调用才可正常进行。</p><h2 id="_2-添加火山方舟供应商" tabindex="-1">2. 添加火山方舟供应商 <a class="header-anchor" href="#_2-添加火山方舟供应商" aria-label="Permalink to &quot;2. 添加火山方舟供应商&quot;">​</a></h2><p>使用火山方舟 OpenAI Compatible 接口作为供应商：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ark.cn-beijing.volces.com/api/v3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --api-key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_ark_api_ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doubao-seed-evolving</span></span></code></pre></div><p>说明：</p><ul><li><code>--name quickstart</code> 是供应商名称，后续消费者授权会用到。</li><li><code>--base-url</code> 是火山方舟 OpenAI 兼容协议的 Base URL。</li><li><code>--api-key</code> 传入火山方舟 API Key。</li><li><code>--model</code> 配置该供应商支持的模型名。</li><li><code>--protocol</code> OpenAI 兼容协议使用 <code>openai</code>，Anthropic 兼容协议使用 <code>anthropic</code>，通常无需显式传入。</li></ul><p>供应商创建是异步操作。命令执行后 CLI 会等待模型网关回到 <code>Running</code> 状态。</p><h2 id="_3-查看供应商" tabindex="-1">3. 查看供应商 <a class="header-anchor" href="#_3-查看供应商" aria-label="Permalink to &quot;3. 查看供应商&quot;">​</a></h2><p>通过 <code>provider show</code> 确认供应商配置，重点检查 <code>Access URL</code>、<code>Base URL</code> 和 <code>Models</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span></span></code></pre></div><p>输出会逐行展示。调用模型网关时使用 <code>Access URL</code>，它是模型网关代理后的访问地址；<code>Base URL</code> 是供应商真实地址。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Provider ID: p-ab*******************uv</span></span>
<span class="line"><span>Name: quickstart</span></span>
<span class="line"><span>Access URL: https://sab****************uv.apigateway-cn-beijing.volceapi.com/p-ab*******************uv</span></span>
<span class="line"><span>Base URL: https://ark.cn-beijing.volces.com/api/v3</span></span>
<span class="line"><span>API Keys: 01******-****-****-****-**********ef</span></span>
<span class="line"><span>Models: doubao-seed-evolving</span></span></code></pre></div><h2 id="_4-创建消费者" tabindex="-1">4. 创建消费者 <a class="header-anchor" href="#_4-创建消费者" aria-label="Permalink to &quot;4. 创建消费者&quot;">​</a></h2><p>创建消费者，并授权它访问 <code>ark</code> 供应商下的所有模型：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allow-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span></span></code></pre></div><p>如果只想授权单个模型，也可以写成：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allow-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart/doubao-seed-evolving</span></span></code></pre></div><p>消费者创建同样是异步操作。命令执行后 CLI 会等待模型网关回到 <code>Running</code> 状态。</p><h2 id="_5-查看消费者密钥" tabindex="-1">5. 查看消费者密钥 <a class="header-anchor" href="#_5-查看消费者密钥" aria-label="Permalink to &quot;5. 查看消费者密钥&quot;">​</a></h2><p>通过 <code>consumer show</code> 获取消费者的 API Key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span></span></code></pre></div><p>输出会逐行展示。调用模型网关时使用 <code>API Keys</code> 中的密钥。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Consumer ID: c-ab*******************uv</span></span>
<span class="line"><span>Name: quickstart</span></span>
<span class="line"><span>API Keys: sk-01****************************ef</span></span>
<span class="line"><span>Authorization: quickstart:*</span></span>
<span class="line"><span>TPM:</span></span>
<span class="line"><span>TPD:</span></span></code></pre></div><h2 id="_6-调用模型网关" tabindex="-1">6. 调用模型网关 <a class="header-anchor" href="#_6-调用模型网关" aria-label="Permalink to &quot;6. 调用模型网关&quot;">​</a></h2><p>使用 <code>show-example</code> 生成 curl 调用示例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agentkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --consumer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quickstart</span></span></code></pre></div><p>OpenAI 兼容的供应商会使用 <code>/chat/completions</code>，Anthropic 兼容的供应商会使用 <code>/messages</code>。输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl &quot;&lt;access_url_from_provider&gt;/chat/completions&quot; \\</span></span>
<span class="line"><span>  -H &quot;Content-Type: application/json&quot; \\</span></span>
<span class="line"><span>  -H &quot;Authorization: Bearer &lt;api_key_from_consumer&gt;&quot; \\</span></span>
<span class="line"><span>  -d &#39;{</span></span>
<span class="line"><span>    &quot;model&quot;: &quot;doubao-seed-evolving&quot;,</span></span>
<span class="line"><span>    &quot;messages&quot;: [</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        &quot;role&quot;: &quot;user&quot;,</span></span>
<span class="line"><span>        &quot;content&quot;: &quot;你是谁？&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }&#39;</span></span></code></pre></div><p>如果配置正确，模型网关会将请求转发到火山方舟，并返回响应。</p>`,42)])])}const g=a(t,[["render",p]]);export{r as __pageData,g as default};
